            INSERT INTO @ids (RemovedIdCity, KeptIdCity)
            SELECT removed.IdCity, kept.IdCity
            FROM @map m
            JOIN [City] removed ON removed.GeoNameId = m.RemovedGeoNameId
            JOIN [City] kept ON kept.GeoNameId = m.KeptGeoNameId;

            UPDATE t SET t.IdCity = i.KeptIdCity FROM [Person] t JOIN @ids i ON t.IdCity = i.RemovedIdCity;
            UPDATE t SET t.IdCity = i.KeptIdCity FROM [GroupChat] t JOIN @ids i ON t.IdCity = i.RemovedIdCity;
            UPDATE t SET t.IdCity = i.KeptIdCity FROM [SingleChat] t JOIN @ids i ON t.IdCity = i.RemovedIdCity;
            UPDATE t SET t.IdCity = i.KeptIdCity FROM [MatchQueue] t JOIN @ids i ON t.IdCity = i.RemovedIdCity;

            DELETE c FROM [City] c JOIN @map m ON c.GeoNameId = m.RemovedGeoNameId;
